#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#include <zephyr/modem/pipe.h>
#include <zephyr/modem/backend/uart.h>

#include <modem_ubx.h>
#include <modem_ubx_utils.h>

#include <string.h>

struct modem_ubx_test_suite_data {
	struct ubx_data ubx_data;
	struct modem_cmd_handler_data cmd_handler_data;
	uint8_t cmd_match_buf[32];
	struct modem_context ubx;
	struct modem_pipe_config pipe_config;
	struct modem_backend_uart_config uart_backend_config;
	struct modem_backend_uart uart_backend;
};

static struct modem_ubx_test_suite_data test_suite_data;

struct test_script {
	const void *cmd;
	size_t cmd_len;
	const void *rsp;
	size_t rsp_len;
	int (*validate)(const void *rsp, size_t rsp_len);
};

struct test_script_runner {
	struct k_work work;
	const struct test_script *script;
	size_t script_len;
	int current;
	struct {
		bool done;
		int ret;
		struct k_sem sem;
	} result;
};

static struct test_script_runner test_script_runner;
static struct k_work_delayable rsp_work;

static void send_rsp_work_handler(struct k_work *item)
{
	struct test_script_runner *runner = &test_script_runner;
	const struct test_script *script = &runner->script[runner->current];

	modem_pipe_receive(&test_suite_data.ubx.iface.pipe, (uint8_t *)script->rsp,
			   script->rsp_len);
}

static int mock_pipe_send(const struct device *d, const uint8_t *buf, int len)
{
	struct test_script_runner *runner = &test_script_runner;
	const struct test_script *script = &runner->script[runner->current];

	zassert_true(runner->current < runner->script_len, "Too many commands sent");
	zassert_not_null(script->cmd, "Command not set in script");
	zassert_equal(len, script->cmd_len, "Invalid command length");
	zassert_mem_equal(buf, script->cmd, script->cmd_len, "Invalid command");

	if (script->rsp) {
		k_work_schedule(&rsp_work, K_MSEC(100));
	}

	return 0;
}

static int mock_pipe_open(const struct device *d)
{
	return 0;
}

static int mock_pipe_close(const struct device *d)
{
	return 0;
}

static const struct modem_pipe_api mock_pipe_api = {
	.open = mock_pipe_open,
	.send = mock_pipe_send,
	.close = mock_pipe_close,
};

DEVICE_DEFINE(mock_pipe, "mock_pipe", NULL, NULL, NULL, NULL, APPLICATION, 0, &mock_pipe_api);

static void test_script_runner_init(struct test_script_runner *runner,
				    const struct test_script *script, size_t script_len)
{
	(void)memset(runner, 0x00, sizeof(*runner));
	runner->script = script;
	runner->script_len = script_len;
	k_sem_init(&runner->result.sem, 0, 1);
}

static void runner_run(struct k_work *item)
{
	struct test_script_runner *runner = CONTAINER_OF(item, struct test_script_runner, work);
	const struct test_script *script = &runner->script[runner->current];

	struct modem_cmd cmds[] = {
		MODEM_CMD(script->cmd, script->cmd_len, script->rsp, script->rsp_len,
			  script->validate),
	};

	runner->result.ret = modem_cmd_handler_send_cmds(
		&test_suite_data.ubx.cmd_handler, &test_suite_data.ubx.iface, cmds,
		ARRAY_SIZE(cmds), K_SECONDS(1));

	runner->result.done = true;
	k_sem_give(&runner->result.sem);
}

static void test_script_runner_run(struct test_script_runner *runner)
{
	k_work_init(&runner->work, runner_run);
	k_work_submit(&runner->work);
}

static int validate_ack(const void *rsp, size_t rsp_len)
{
	const struct ubx_ack *ack = rsp;

	if (rsp_len != sizeof(*ack)) {
		return -EIO;
	}

	if (ubx_utils_header_valid(&ack->hdr) == false) {
		return -EIO;
	}

	if (ubx_utils_checksum_valid((const uint8_t *)ack, sizeof(*ack)) == false) {
		return -EIO;
	}

	return 0;
}

static void *modem_ubx_test_setup(void)
{
	k_work_init_delayable(&rsp_work, send_rsp_work_handler);
	return NULL;
}

static void modem_ubx_test_before(void *f)
{
	(void)memset(&test_suite_data, 0x00, sizeof(test_suite_data));

	test_suite_data.uart_backend_config.uart = DEVICE_GET(mock_pipe);
	test_suite_data.pipe_config.backend = &test_suite_data.uart_backend.backend;
	test_suite_data.pipe_config.iface_data = &test_suite_data.uart_backend;
	test_suite_data.pipe_config.iface_config = &test_suite_data.uart_backend_config;

	modem_cmd_handler_init(&test_suite_data.ubx.cmd_handler,
			       &test_suite_data.cmd_handler_data, test_suite_data.cmd_match_buf,
			       sizeof(test_suite_data.cmd_match_buf));

	modem_pipe_init(&test_suite_data.ubx.iface.pipe, &test_suite_data.pipe_config);

	ubx_init(&test_suite_data.ubx, &test_suite_data.ubx_data);
}

ZTEST(modem_ubx, test_cmd_no_rsp_is_non_blocking)
{
	struct ubx_cmd cmd = {
		.hdr = UBX_HEADER_DEFAULT,
		.cls = UBX_CLASS_CFG,
		.id = UBX_CFG_ID_ANT,
		.len = 0,
	};

	ubx_utils_header_update(&cmd.hdr, sizeof(cmd) - sizeof(cmd.hdr));
	ubx_utils_checksum_update((uint8_t *)&cmd, sizeof(cmd));

	struct test_script script[] = {
		{
			.cmd = &cmd,
			.cmd_len = sizeof(cmd),
		},
	};

	test_script_runner_init(&test_script_runner, script, ARRAY_SIZE(script));
	test_script_runner_run(&test_script_runner);

	zassert_ok(k_sem_take(&test_script_runner.result.sem, K_SECONDS(1)));
	zassert_true(test_script_runner.result.done, "Command should be done");
	zassert_ok(test_script_runner.result.ret, "Command should succeed");
}

ZTEST(modem_ubx, test_cmd_rsp_blocks_and_receives_rsp)
{
	struct ubx_cmd cmd = {
		.hdr = UBX_HEADER_DEFAULT,
		.cls = UBX_CLASS_CFG,
		.id = UBX_CFG_ID_ANT,
		.len = 0,
	};

	ubx_utils_header_update(&cmd.hdr, sizeof(cmd) - sizeof(cmd.hdr));
	ubx_utils_checksum_update((uint8_t *)&cmd, sizeof(cmd));

	struct ubx_ack ack = {
		.hdr = UBX_HEADER_DEFAULT,
		.cls = UBX_CLASS_ACK,
		.id = UBX_ACK_ID_ACK,
		.len = 2,
		.ack_cls = UBX_CLASS_CFG,
		.ack_id = UBX_CFG_ID_ANT,
	};

	ubx_utils_header_update(&ack.hdr, sizeof(ack) - sizeof(ack.hdr));
	ubx_utils_checksum_update((uint8_t *)&ack, sizeof(ack));

	struct test_script script[] = {
		{
			.cmd = &cmd,
			.cmd_len = sizeof(cmd),
			.rsp = &ack,
			.rsp_len = sizeof(ack),
			.validate = validate_ack,
		},
	};

	test_script_runner_init(&test_script_runner, script, ARRAY_SIZE(script));
	test_script_runner_run(&test_script_runner);

	zassert_false(test_script_runner.result.done, "Command should be blocking");
	zassert_ok(k_sem_take(&test_script_runner.result.sem, K_SECONDS(1)));
	zassert_true(test_script_runner.result.done, "Command should be done");
	zassert_ok(test_script_runner.result.ret, "Command should succeed");
}

ZTEST_SUITE(modem_ubx, NULL, modem_ubx_test_setup, modem_ubx_test_before, NULL, NULL);
